        group.MapPost("/categories",async (SaveTrainingCategory value,ITrainingAdministrationReader reader,CancellationToken token)=>Results.Created("/api/training/administration/overview",new{id=await reader.SaveCategoryAsync(null,value,token)})).RequireAuthorization(AdminCorePermissions.TrainingCatalogManage);
        group.MapPut("/categories/{id:guid}",async (Guid id,SaveTrainingCategory value,ITrainingAdministrationReader reader,CancellationToken token)=>Results.Ok(new{id=await reader.SaveCategoryAsync(id,value,token)})).RequireAuthorization(AdminCorePermissions.TrainingCatalogManage);
